        rom[908] = 94'h5d81bb00f605ec0;
        rom[909] = 94'h7d81fb007604ec0;
        rom[910] = 94'h3e817d017a06f40;
        rom[911] = 94'h9e803d03fa03f40;
        rom[912] = 94'hdf80bf02fe01fc0;
        rom[913] = 94'h3f807f007e00fc0;
    end
    reg wv = 1'b0;                       // a ROM word is being executed this clock
    reg [WIDTH-1:0] word_r = 0;
    wire [WIDTH-1:0] word = wv ? word_r : {WIDTH{1'b0}};

    // ---------------------------------------------------------------- sequencer
    // start in cycle c0 -> run (ROM addresses) in c0+1 .. c0+NW, word k visible in c0+2+k,
    // the last word executes in c0+NW+1 and done is high in c0+NW+2: cycles = NW + 2.
    reg run = 1'b0, inv_r = 1'b0;
    reg [9:0] pc = 0, end_pc = 0;
    reg [15:0] cyc = 0;
    assign busy = run | wv | done;
    assign cycles = cyc;
    always @(posedge clk) begin
        done <= 1'b0;
        // address gated by `run`: a real gate between the pc flip-flops and the block-RAM
        // address pins (a direct flip-flop drive fails nextpnr's Gowin BSRAM hold check)
        word_r <= rom[pc & {PCW{run}}];
        wv <= run;
        if (rst) begin
            run <= 1'b0; wv <= 1'b0;
        end else if (start && !(run | wv)) begin      // also accepted in the done clock
            run <= 1'b1; inv_r <= inv; cyc <= 16'd1;
            pc     <= inv ? NW_F : 0;
            end_pc <= inv ? TOTAL - 1 : NW_F - 1;
        end else if (run | wv) begin
            cyc <= cyc + 1'b1;
            if (run) begin
                pc <= pc + 1'b1;
                if (pc == end_pc) run <= 1'b0;
            end
            if (wv && !run) done <= 1'b1;
        end
    end

    // ---------------------------------------------------------------- host address decode
    wire [BB-1:0] h_bank = {
^(h_idx & 8'b10110110), ^(h_idx & 8'b01101101)};
    wire [AW-1:0] h_addr = {h_idx[7], h_idx[6], h_idx[5], h_idx[4], h_idx[3], h_idx[2]};
    reg  [BB-1:0] h_bank_q = 0;
    always @(posedge clk) h_bank_q <= h_bank;

    // ---------------------------------------------------------------- banks
    wire [12*B-1:0] rd_flat;
    wire [12*4-1:0] outs_flat;
    (* ram_style = "block" *) reg [11:0] mem0 [0:63];
    reg [11:0] rd0 = 0;
    reg [11:0] wdr0 = 0;                 // write-crossbar register
    wire [AW-1:0] ra0 = wv ? word[5:0] : h_addr;
    wire [BB-1:0] wsel0 = word[14:13];
    wire          ctl_we0 = word[6];
    wire [11:0]   wdsel0 = outs_flat[wsel0 * 12 +: 12];
    wire [11:0]   wd0  = wv ? wdr0 : h_wdata;
    wire          we0  = wv ? ctl_we0 : (h_we & (h_bank == 0));
    wire [AW-1:0] wa0  = wv ? word[12:7] : h_addr;
    always @(posedge clk) begin
        if (we0) mem0[wa0] <= wd0;
        rd0 <= mem0[ra0];
        wdr0 <= wdsel0;
    end
    assign rd_flat[11:0] = rd0;
    (* ram_style = "block" *) reg [11:0] mem1 [0:63];
    reg [11:0] rd1 = 0;
    reg [11:0] wdr1 = 0;                 // write-crossbar register
    wire [AW-1:0] ra1 = wv ? word[20:15] : h_addr;
    wire [BB-1:0] wsel1 = word[29:28];
    wire          ctl_we1 = word[21];
    wire [11:0]   wdsel1 = outs_flat[wsel1 * 12 +: 12];
    wire [11:0]   wd1  = wv ? wdr1 : h_wdata;
    wire          we1  = wv ? ctl_we1 : (h_we & (h_bank == 1));
    wire [AW-1:0] wa1  = wv ? word[27:22] : h_addr;
    always @(posedge clk) begin
        if (we1) mem1[wa1] <= wd1;
        rd1 <= mem1[ra1];
        wdr1 <= wdsel1;
    end
    assign rd_flat[23:12] = rd1;
    (* ram_style = "block" *) reg [11:0] mem2 [0:63];
    reg [11:0] rd2 = 0;
    reg [11:0] wdr2 = 0;                 // write-crossbar register
    wire [AW-1:0] ra2 = wv ? word[35:30] : h_addr;
    wire [BB-1:0] wsel2 = word[44:43];
    wire          ctl_we2 = word[36];
    wire [11:0]   wdsel2 = outs_flat[wsel2 * 12 +: 12];
    wire [11:0]   wd2  = wv ? wdr2 : h_wdata;
    wire          we2  = wv ? ctl_we2 : (h_we & (h_bank == 2));
    wire [AW-1:0] wa2  = wv ? word[42:37] : h_addr;
    always @(posedge clk) begin
        if (we2) mem2[wa2] <= wd2;
        rd2 <= mem2[ra2];
        wdr2 <= wdsel2;
    end
    assign rd_flat[35:24] = rd2;
    (* ram_style = "block" *) reg [11:0] mem3 [0:63];
    reg [11:0] rd3 = 0;
    reg [11:0] wdr3 = 0;                 // write-crossbar register
    wire [AW-1:0] ra3 = wv ? word[50:45] : h_addr;
    wire [BB-1:0] wsel3 = word[59:58];
    wire          ctl_we3 = word[51];
    wire [11:0]   wdsel3 = outs_flat[wsel3 * 12 +: 12];
    wire [11:0]   wd3  = wv ? wdr3 : h_wdata;
    wire          we3  = wv ? ctl_we3 : (h_we & (h_bank == 3));
    wire [AW-1:0] wa3  = wv ? word[57:52] : h_addr;
    always @(posedge clk) begin
        if (we3) mem3[wa3] <= wd3;
        rd3 <= mem3[ra3];
        wdr3 <= wdsel3;
    end
    assign rd_flat[47:36] = rd3;
    assign h_rdata = rd_flat[h_bank_q * 12 +: 12];

    // ---------------------------------------------------------------- lanes
    reg [11:0] a_in0 = 0, b_in0 = 0, z_in0 = 0;
    reg        v_in0 = 1'b0;
    always @(posedge clk) begin
        a_in0 <= rd_flat[word[62:61] * 12 +: 12];
        b_in0 <= rd_flat[word[64:63] * 12 +: 12];
        z_in0 <= word[76:65];
        v_in0 <= word[60];
    end
    wire        vo0;
    wire [11:0] o0_0, o1_0;
    mlkem_bfly lane0 (.clk(clk), .rst(rst), .v_in(v_in0), .mode(inv_r), .a(a_in0), .b(b_in0),
                        .z(z_in0), .v_out(vo0), .o0(o0_0), .o1(o1_0));
    assign outs_flat[11:0] = o0_0;
    assign outs_flat[23:12] = o1_0;
    reg [11:0] a_in1 = 0, b_in1 = 0, z_in1 = 0;
    reg        v_in1 = 1'b0;
    always @(posedge clk) begin
        a_in1 <= rd_flat[word[79:78] * 12 +: 12];
        b_in1 <= rd_flat[word[81:80] * 12 +: 12];
        z_in1 <= word[93:82];
        v_in1 <= word[77];
    end
    wire        vo1;
    wire [11:0] o0_1, o1_1;
    mlkem_bfly lane1 (.clk(clk), .rst(rst), .v_in(v_in1), .mode(inv_r), .a(a_in1), .b(b_in1),
                        .z(z_in1), .v_out(vo1), .o0(o0_1), .o1(o1_1));
    assign outs_flat[35:24] = o0_1;
    assign outs_flat[47:36] = o1_1;
endmodule
